// tests/constants.test.js
const { STATUS_BY_MARKER, STATUS_BY_KEY, STATUSES, SUBTASK_STATUS_CYCLE, TASK_LINE_RE } = require("../js/constants");

test("STATUS_BY_MARKER maps aliases", () => {
  expect(STATUS_BY_MARKER.get("x").key).toBe("done");
  expect(STATUS_BY_MARKER.get("X").key).toBe("done");
  expect(STATUS_BY_MARKER.get(" ").key).toBe("open");
  expect(STATUS_BY_MARKER.get("")).toBe(STATUS_BY_MARKER.get(" "));
});

test("SUBTASK_STATUS_CYCLE contains only open/progress/done", () => {
  expect(SUBTASK_STATUS_CYCLE.map(s => s.key)).toEqual(["open", "progress", "done"]);
});

test("TASK_LINE_RE matches task lines", () => {
  expect("- [ ] hello".match(TASK_LINE_RE)?.[2]).toBe(" ");
  expect("  - [x] done".match(TASK_LINE_RE)?.[2]).toBe("x");
  expect("not a task".match(TASK_LINE_RE)).toBeNull();
  expect("- [] no bracket space".match(TASK_LINE_RE)).toBeNull();
});
