// tests/block-ids.test.js
const mod = require("../js/plugin/block-ids");
// mix in as `this` via Object.assign or bind
const ctx = Object.assign({}, mod);

test("hashString is deterministic", () => {
  expect(ctx.hashString("hello")).toBe(ctx.hashString("hello"));
});

test("hashString differs on different input", () => {
  expect(ctx.hashString("a")).not.toBe(ctx.hashString("b"));
});

test("hashString handles empty string", () => {
  expect(() => ctx.hashString("")).not.toThrow();
});

test("createUniqueBlockId avoids collisions", () => {
  const file = { path: "note.md" };
  const used = new Set();
  const id1 = ctx.createUniqueBlockId(file, 0, "task", used);
  used.add(id1);
  const id2 = ctx.createUniqueBlockId(file, 0, "task", used);
  expect(id1).not.toBe(id2);
  expect(id2).toMatch(/-2$/);
});

test("replaceOrInsertKanbanBlock replaces existing block", () => {
  const content = "before\n\n<!-- task-kanban:start -->\nold\n<!-- task-kanban:end -->\n\nafter";
  const result = ctx.replaceOrInsertKanbanBlock(content, "<!-- task-kanban:start -->\nnew\n<!-- task-kanban:end -->");
  expect(result).toContain("new");
  expect(result).not.toContain("old");
  expect(result).toContain("before");
  expect(result).toContain("after");
});

test("replaceOrInsertKanbanBlock inserts when no block exists", () => {
  const content = "# Title\n\ntask line";
  const block = "<!-- task-kanban:start -->\n<!-- task-kanban:end -->";
  const result = ctx.replaceOrInsertKanbanBlock(content, block);
  expect(result).toContain(block);
  expect(result).toContain("# Title");
});

test("removeKanbanBlock returns content unchanged when no block", () => {
  const content = "no kanban here";
  expect(ctx.removeKanbanBlock(content)).toBe(content);
});

test("findTopInsertIndex skips frontmatter", () => {
  const lines = ["---", "title: foo", "---", "", "# Heading"];
  expect(ctx.findTopInsertIndex(lines)).toBe(4);
});

test("findTopInsertIndex returns 0 without frontmatter", () => {
  const lines = ["# Heading", "content"];
  expect(ctx.findTopInsertIndex(lines)).toBe(0);
});

test("ensureTaskBlockIds adds IDs to tasks", () => {
  const file = { path: "note.md" };
  const content = "- [ ] task one\n- [x] task two";
  const result = ctx.ensureTaskBlockIds(file, content);
  expect(result.match(/\^tk-/g)).toHaveLength(2);
});

test("ensureTaskBlockIds skips tasks inside kanban block", () => {
  const file = { path: "note.md" };
  const content = "<!-- task-kanban:start -->\n- [ ] inside\n<!-- task-kanban:end -->";
  const result = ctx.ensureTaskBlockIds(file, content);
  expect(result).not.toMatch(/\^tk-/);
});

test("ensureTaskBlockIds does not duplicate existing IDs", () => {
  const file = { path: "note.md" };
  const content = "- [ ] task ^existing-id";
  const result = ctx.ensureTaskBlockIds(file, content);
  expect((result.match(/\^/g) || []).length).toBe(1);
});
