const mod = require("../js/plugin/format");
const ctx = Object.assign({}, mod);

test("escapeTableText escapes special chars", () => {
  expect(ctx.escapeTableText("<b> & 'a' | x")).toBe("&lt;b&gt; &amp; 'a' &#124; x");
});

