  expect(ctx.escapeTableText("line1\nline2")).toBe("line1 line2");
  expect(ctx.escapeTableText("line1\r\nline2")).toBe("line1 line2");
});

test("escapeTableText handles empty string", () => {
  expect(ctx.escapeTableText("")).toBe("");
});

test("escapeAttribute escapes double quotes", () => {
  expect(ctx.escapeAttribute('say "hi"')).toBe("say &quot;hi&quot;");
});

test("escapeMarkdownInline escapes markdown chars", () => {
  const result = ctx.escapeMarkdownInline("*bold* _italic_ [link]");
  expect(result).toBe("\\*bold\\* \\_italic\\_ \\[link\\]");
});

test("formatKanbanCellItem renders card with blockId", () => {
  const task = { line: 5, blockId: "abc", text: "do thing", heading: "", subtasks: [], status: { key: "open" } };
  const html = ctx.formatKanbanCellItem(task);
  expect(html).toContain('data-block-id="abc"');
  expect(html).toContain('draggable="true"');
  expect(html).toContain("do thing");
});

test("formatKanbanCellItem renders card without blockId", () => {
  const task = { line: 3, blockId: "", text: "no id", heading: "", subtasks: [], status: { key: "open" } };
  const html = ctx.formatKanbanCellItem(task);
  expect(html).not.toContain("data-block-id");
  expect(html).not.toContain("draggable");
});

test("formatKanbanCellItem includes heading when present", () => {
  const task = { line: 1, blockId: "", text: "task", heading: "My Section", subtasks: [], status: { key: "open" } };
  const html = ctx.formatKanbanCellItem(task);
  expect(html).toContain("My Section");
  expect(html).toContain("task-kanban-inline-heading");
});

test("formatInlineSubtasks renders recursively", () => {
  const subtasks = [
    { line: 2, blockId: "s1", text: "sub", status: { key: "open", title: "Open", icon: "⬜" }, subtasks: [] }
  ];
  const html = ctx.formatInlineSubtasks(subtasks);
  expect(html).toContain("task-kanban-inline-subtasks");
  expect(html).toContain("sub");
});
