// tests/tasks.test.js
const mod = require("../js/plugin/tasks");
const { STATUSES } = require("../js/constants");

// getIndentLevel is pure; bind ctx with hashString stub
const ctx = Object.assign({
  getIndentLevel: mod.getIndentLevel,
  hashString: (s) => "hash",
}, mod);

test("getIndentLevel counts spaces", () => {
  expect(ctx.getIndentLevel("    ")).toBe(4);
  expect(ctx.getIndentLevel("  ")).toBe(2);
  expect(ctx.getIndentLevel("")).toBe(0);
});

test("getIndentLevel counts tabs as 4", () => {
  expect(ctx.getIndentLevel("\t")).toBe(4);
  expect(ctx.getIndentLevel("\t\t")).toBe(8);
  expect(ctx.getIndentLevel("\t  ")).toBe(6);
});

test("scanTasksInContent returns empty for no tasks", () => {
  const file = { path: "f.md" };
  const result = ctx.scanTasksInContent(file, "# Heading\nno tasks here");
  expect(result).toEqual([]);
});

test("scanTasksInContent parses basic task", () => {
  const file = { path: "f.md" };
  const [task] = ctx.scanTasksInContent(file, "- [ ] hello world");
  expect(task.text).toBe("hello world");
  expect(task.status.key).toBe("open");
  expect(task.line).toBe(0);
});

test("scanTasksInContent extracts heading context", () => {
  const file = { path: "f.md" };
  const content = "## My Section\n- [x] done task";
  const [task] = ctx.scanTasksInContent(file, content);
  expect(task.heading).toBe("My Section");
  expect(task.status.key).toBe("done");
});

test("scanTasksInContent builds subtask tree", () => {
  const file = { path: "f.md" };
  const content = "- [ ] parent\n  - [x] child";
  const roots = ctx.scanTasksInContent(file, content);
  expect(roots).toHaveLength(1);
  expect(roots[0].subtasks).toHaveLength(1);
  expect(roots[0].subtasks[0].text).toBe("child");
});

test("scanTasksInContent skips lines inside kanban block", () => {
  const file = { path: "f.md" };
  const content = "<!-- task-kanban:start -->\n- [ ] inside\n<!-- task-kanban:end -->\n- [ ] outside";
  const roots = ctx.scanTasksInContent(file, content);
  expect(roots).toHaveLength(1);
  expect(roots[0].text).toBe("outside");
});

test("scanTasksInContent extracts blockId", () => {
  const file = { path: "f.md" };
  const [task] = ctx.scanTasksInContent(file, "- [ ] my task ^block-abc");
  expect(task.blockId).toBe("block-abc");
  expect(task.text).toBe("my task");
});

test("scanTasksInContent counts priority emoji", () => {
  const file = { path: "f.md" };
  const [task] = ctx.scanTasksInContent(file, "- [ ] 🔥🔥 urgent");
  expect(task.priority).toBe(2);
});

test("scanTasksInContent handles CRLF", () => {
  const file = { path: "f.md" };
  const [task] = ctx.scanTasksInContent(file, "- [ ] task\r\n- [x] done");
  expect(task.text).toBe("task");
});

test("scanTasksInContent unknown marker defaults to open", () => {
  const file = { path: "f.md" };
  const [task] = ctx.scanTasksInContent(file, "- [~] unknown marker task");
  expect(task.status.key).toBe("open");
});
