// tests/state.test.js
const { STATUSES, SUBTASK_STATUS_CYCLE, STATUS_BY_KEY } = require("../js/constants");
const mod = require("../js/plugin/state");

const ctx = Object.assign({
  hashString: (s) => "fakehash",
  taskKanbanSortMode: "default",
  taskKanbanTouchedAt: {},
  getTaskTouchedKey: mod.getTaskTouchedKey,
}, mod);

test("getNextStatus wraps around", () => {
  const last = STATUSES[STATUSES.length - 1];
  const next = ctx.getNextStatus(last);
  expect(next).toBe(STATUSES[0]);
});

test("getNextStatus advances correctly", () => {
  expect(ctx.getNextStatus(STATUSES[0])).toBe(STATUSES[1]);
});

test("getNextSubtaskStatus handles unknown status", () => {
  const result = ctx.getNextSubtaskStatus({ key: "unknown" });
  expect(result).toBe(SUBTASK_STATUS_CYCLE[0]);
});

test("getNextSubtaskStatus wraps around", () => {
  const last = SUBTASK_STATUS_CYCLE[SUBTASK_STATUS_CYCLE.length - 1];
  expect(ctx.getNextSubtaskStatus(last)).toBe(SUBTASK_STATUS_CYCLE[0]);
});

test("getTaskTouchedKey returns empty for null task", () => {
  expect(ctx.getTaskTouchedKey(null)).toBe("");
  expect(ctx.getTaskTouchedKey(undefined)).toBe("");
});

test("getTaskTouchedKey uses blockId when present", () => {
  const key = ctx.getTaskTouchedKey({ file: { path: "note.md" }, blockId: "abc", line: 5 });
  expect(key).toBe("note.md#abc");
});

test("getTaskTouchedKey uses line+hash when no blockId", () => {
  const key = ctx.getTaskTouchedKey({ file: { path: "note.md" }, blockId: "", line: 3, raw: "- [ ] hi" });
  expect(key).toMatch(/^note\.md:3:/);
});

test("getInlineLine parses valid number", () => {
  const el = { getAttribute: (a) => "42" };
  expect(ctx.getInlineLine(el)).toBe(42);
});

test("getInlineLine returns null for NaN", () => {
  const el = { getAttribute: (a) => "abc" };
  expect(ctx.getInlineLine(el)).toBeNull();
});

test("getInlineLine returns null for null element", () => {
  expect(ctx.getInlineLine(null)).toBeNull();
});

test("getEventElement returns element unchanged", () => {
  const el = document.createElement("div");
  expect(ctx.getEventElement(el)).toBe(el);
});

test("getEventElement returns parentElement for non-Element", () => {
  const parent = document.createElement("div");
  const textNode = { parentElement: parent };
  expect(ctx.getEventElement(textNode)).toBe(parent);
});
